import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as r,ak as n}from"./chunks/framework.DC-k2h36.js";const s="/projects/esp32Sensor/en/latest/assets/1.Dy2edZcG.webp",i="/projects/esp32Sensor/en/latest/assets/2.5pyYqAf6.webp",l="/projects/esp32Sensor/en/latest/assets/3.DN91HREZ.webp",d="/projects/esp32Sensor/en/latest/assets/4.Bij2Hxhv.webp",c="/projects/esp32Sensor/en/latest/assets/5.RbN2lbpo.webp",v=JSON.parse('{"title":"5. Sound Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5. Sound Sensor.md","filePath":"docs/5. Sound Sensor.md"}'),h={name:"docs/5. Sound Sensor.md"};function p(m,e,g,u,_,b){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-sound-sensor" tabindex="-1">5. Sound Sensor <a class="header-anchor" href="#_5-sound-sensor" aria-label="Permalink to &quot;5. Sound Sensor&quot;">​</a></h1><h2 id="_5-1-introduction" tabindex="-1">5.1 Introduction <a class="header-anchor" href="#_5-1-introduction" aria-label="Permalink to &quot;5.1 Introduction&quot;">​</a></h2><p>The sound sensor detects ambient sound levels. It is widely used in sound-activated robots, sound-triggered switches, sound alarms, and related equipment.</p><img loading="lazy" height="1156" width="1156" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_5-2-technical-specifications" tabindex="-1">5.2 Technical Specifications <a class="header-anchor" href="#_5-2-technical-specifications" aria-label="Permalink to &quot;5.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Microphone type</td><td style="text-align:center;">Electret condenser</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 18.7 mm</td></tr></tbody></table><h2 id="_5-3-hands-on-project" tabindex="-1">5.3 Hands-On Project <a class="header-anchor" href="#_5-3-hands-on-project" aria-label="Permalink to &quot;5.3 Hands-On Project&quot;">​</a></h2><h3 id="_5-3-1-project-overview" tabindex="-1">5.3.1 Project Overview <a class="header-anchor" href="#_5-3-1-project-overview" aria-label="Permalink to &quot;5.3.1 Project Overview&quot;">​</a></h3><p>This project uses the sound sensor to collect analog sound volume values from the environment and outputs them via the serial port. Varying ambient volume by clapping or speaking allows observation of changing values in the serial monitor, demonstrating the volume acquisition logic of the sound sensor.</p><h3 id="_5-3-2-hardware-wiring" tabindex="-1">5.3.2 Hardware Wiring <a class="header-anchor" href="#_5-3-2-hardware-wiring" aria-label="Permalink to &quot;5.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the sound sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="620" src="'+i+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_5-3-3-adding-extensions" tabindex="-1">5.3.3 Adding Extensions <a class="header-anchor" href="#_5-3-3-adding-extensions" aria-label="Permalink to &quot;5.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Sound sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_5-3-4-complete-program-and-analysis" tabindex="-1">5.3.4 Complete Program and Analysis <a class="header-anchor" href="#_5-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;5.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the volume analog value of the sound sensor on port P5 is continuously read.</p></li><li><p>The collected volume analog value is printed via the serial port.</p></li><li><p>A 0.5 s delay is executed to refresh data quickly and track variations in sound levels.</p></li></ol><img loading="lazy" height="269" width="564" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/05 Sound Sensor.sb3</a>.</strong></p></div><h3 id="_5-3-5-program-upload" tabindex="-1">5.3.5 Program Upload <a class="header-anchor" href="#_5-3-5-program-upload" aria-label="Permalink to &quot;5.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_5-3-6-program-outcome" tabindex="-1">5.3.6 Program Outcome <a class="header-anchor" href="#_5-3-6-program-outcome" aria-label="Permalink to &quot;5.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, observe the serial monitor in the lower-right corner of the programming software. In quiet environments, the serial output displays smaller values. Clapping or speaking loudly increases the detected volume and raises the printed values, with readings ranging from 0 to 100.</p><img loading="lazy" height="904" width="1108" src="'+c+'" class="common_img" style="width:500px;">',26)])])}const x=o(h,[["render",p]]);export{v as __pageData,x as default};
